        use crate::options::parser::TakesValue;

        #[rustfmt::skip]
        return match self {
            Self::BadArgument(arg, attempt) => {
                if let TakesValue::Necessary(Some(values)) = arg.takes_value {
                    write!(
                        f,
                        "Option {} has no {:?} setting ({})",
                        arg,
                        attempt,
                        Choices(values)
